
training_examples = [
    {
        "question": "What is the total sales revenue?",
        "sql": "SELECT SUM(amount) AS total_revenue FROM sales;"
    },
    {
        "question": "Show total revenue generated by each city.",
        "sql": """
            SELECT city, SUM(amount) AS total_revenue
            FROM sales
            GROUP BY city
            ORDER BY total_revenue DESC;
        """
    },
    {
        "question": "What is the average sale amount?",
        "sql": "SELECT AVG(amount) AS average_sale FROM sales;"
    },
    {
        "question": "Show total quantity sold for each product.",
        "sql": """
            SELECT product, SUM(quantity) AS total_quantity
            FROM sales
            GROUP BY product
            ORDER BY total_quantity DESC;
        """
    },
    {
        "question": "Show revenue by product category.",
        "sql": """
            SELECT category, SUM(amount) AS total_revenue
            FROM sales
            GROUP BY category
            ORDER BY total_revenue DESC;
        """
    }
]
